import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

custom_avg_pool_3d_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <vector>

// A naive 3D Average Pooling CUDA kernel
__global__ void avg_pool3d_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    const int batch_size,
    const int channels,
    const int depth_in,
    const int height_in,
    const int width_in,
    const int depth_out,
    const int height_out,
    const int width_out,
    const int kernel_size,
    const int stride,
    const int padding)
{
    // Calculate global output index
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elems = batch_size * channels * depth_out * height_out * width_out;
    if (idx >= total_elems) {
        return;
    }

    // Decode n, c, dz, hy, wx from the linear index
    int w_out = idx % width_out;
    int temp_idx = idx / width_out;
    int h_out = temp_idx % height_out;
    temp_idx /= height_out;
    int d_out = temp_idx % depth_out;
    temp_idx /= depth_out;
    int c = temp_idx % channels;
    int n = temp_idx / channels;

    // Compute the start and end indices along each dimension in the input
    int d_start = d_out * stride - padding;
    int h_start = h_out * stride - padding;
    int w_start = w_out * stride - padding;

    int d_end = d_start + kernel_size;
    int h_end = h_start + kernel_size;
    int w_end = w_start + kernel_size;

    // Clamp boundaries
    d_start = max(d_start, 0);
    h_start = max(h_start, 0);
    w_start = max(w_start, 0);

    d_end = min(d_end, depth_in);
    h_end = min(h_end, height_in);
    w_end = min(w_end, width_in);

    float sum_val = 0.0f;
    int count = 0;

    // Accumulate values within the pooling window
    for (int dz = d_start; dz < d_end; dz++) {
        for (int hy = h_start; hy < h_end; hy++) {
            for (int wx = w_start; wx < w_end; wx++) {
                int in_idx = n * (channels * depth_in * height_in * width_in)
                           + c * (depth_in * height_in * width_in)
                           + dz * (height_in * width_in)
                           + hy * width_in
                           + wx;
                sum_val += input[in_idx];
                count++;
            }
        }
    }

    // Compute average
    float avg_val = count == 0 ? 0.0f : sum_val / static_cast<float>(count);

    // Write to output
    int out_idx = idx;
    output[out_idx] = avg_val;
}

torch::Tensor avg_pool3d_cuda(
    torch::Tensor x,
    int kernel_size,
    int stride,
    int padding)
{
    // Get input sizes
    auto sizes = x.sizes();
    int batch_size = sizes[0];
    int channels   = sizes[1];
    int depth_in   = sizes[2];
    int height_in  = sizes[3];
    int width_in   = sizes[4];

    // Calculate output dimensions
    int depth_out  = (depth_in + 2 * padding - kernel_size) / stride + 1;
    int height_out = (height_in + 2 * padding - kernel_size) / stride + 1;
    int width_out  = (width_in + 2 * padding - kernel_size) / stride + 1;

    // Prepare output tensor
    auto options = x.options();
    auto out = torch::empty({batch_size, channels, depth_out, height_out, width_out}, options);

    int total_elems = batch_size * channels * depth_out * height_out * width_out;

    const int block_size = 256;
    const int grid_size = (total_elems + block_size - 1) / block_size;

    avg_pool3d_kernel<<<grid_size, block_size>>>(
        x.data_ptr<float>(),
        out.data_ptr<float>(),
        batch_size,
        channels,
        depth_in,
        height_in,
        width_in,
        depth_out,
        height_out,
        width_out,
        kernel_size,
        stride,
        padding
    );
    return out;
}
"""

custom_avg_pool_3d_cpp_source = r"""
torch::Tensor avg_pool3d_cuda(
    torch::Tensor x,
    int kernel_size,
    int stride,
    int padding);
"""

# Build/Load the custom CUDA operator
custom_avg_pool_3d = load_inline(
    name="custom_avg_pool_3d",
    cpp_sources=custom_avg_pool_3d_cpp_source,
    cuda_sources=custom_avg_pool_3d_source,
    functions=["avg_pool3d_cuda"],
    verbose=False
)

class ModelNew(nn.Module):
    """
    Custom 3D Average Pooling using a custom CUDA kernel.
    """
    def __init__(self, kernel_size: int, stride: int = None, padding: int = 0):
        super(ModelNew, self).__init__()
        self.kernel_size = kernel_size
        self.stride = stride if stride is not None else kernel_size
        self.padding = padding

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return custom_avg_pool_3d.avg_pool3d_cuda(
            x, self.kernel_size, self.stride, self.padding
        )
